'use strict';

const http = require('node:http');
const { Readable } = require('node:stream');

const MAX_BODY = 1024;
const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 8080;

function send(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(body),
  });
  res.end(body);
}

const server = http.createServer((req, res) => {
  if (req.method !== 'POST') {
    return send(res, 405, { error: 'method_not_allowed' });
  }

  let size = 0;
  const chunks = [];
  let aborted = false;

  req.on('data', (chunk) => {
    if (aborted) return;
    size += chunk.length;
    if (size > MAX_BODY) {
      // Limit crossed: stop buffering immediately and tear down the request
      // so we never hold the full payload in memory.
      aborted = true;
      chunks.length = 0;
      req.destroy(); // abort reading from the socket
      return send(res, 413, { error: 'payload_too_large' });
    }
    chunks.push(chunk);
  });

  req.on('error', () => {
    /* client/aborted connection noise; response already handled or gone */
  });

  req.on('end', () => {
    if (aborted) return;
    const raw = Buffer.concat(chunks).toString('utf8');
    try {
      const parsed = JSON.parse(raw);
      send(res, 200, parsed);
    } catch (_e) {
      send(res, 400, { error: 'invalid_json' });
    }
  });
});

// Safety net: if a handler ever throws, don't take down the process.
process.on('uncaughtException', (err) => {
  console.error('uncaught exception:', err.message);
});
process.on('unhandledRejection', (err) => {
  console.error('unhandled rejection:', err);
});

server.listen(PORT, () => {
  console.log(`echo server listening on :${PORT} (max body ${MAX_BODY} bytes)`);
});

if (require.main === module && process.env.ECHO_NO_GRACEFUL == null) {
  const shutdown = () => {
    server.close(() => process.exit(0));
    setTimeout(() => process.exit(0), 1500).unref();
  };
  process.on('SIGINT', shutdown);
  process.on('SIGTERM', shutdown);
}
"})
